// =================================================================
// pdf-script.js — Upload this file to GitHub
// Full PDF generator for chemistry blog
// generatePostPDF() is called by the Blogger snippet on click
// =================================================================
// ============================================================
//         EASY SETTINGS — CHANGE ANYTHING HERE FREELY
//         All sizes are in millimeters (mm) unless noted
// ============================================================
const CONFIG = {

  // ── PAGE MARGINS ──────────────────────────────────────────
  marginTop:    20,   // Space from top of page to content
  marginBottom: 15,   // Space from bottom of page to content
  marginLeft:   15,   // Space from left edge to content
  marginRight:  15,   // Space from right edge to content

  // ── HEADER (the "Sudhir Nama" bar at the top) ─────────────
  headerFontSize:   19,  // Font size of "Sudhir Nama" in header
  headerHeight:     20,  // Height of the header bar
  headerGapBelow:   35,  // Space between header bar and post title below it

  // ── POST TITLE ────────────────────────────────────────────
  postTitleFontSize: 15,  // Font size of the big post title
  postTitleLineHeight: 8, // Space between lines in the post title (increase to add more breathing room)
  postTitleGapBelow: 1,   // Space below post title (before the green divider line)

  // ── DIVIDER LINE ──────────────────────────────────────────
  dividerGapBelow:   10,  // Space below the green divider line before content starts

  // ── PARAGRAPHS ────────────────────────────────────────────
  paragraphFontSize:   12, // Font size of normal paragraph text
  paragraphLineHeight:  6.8, // Space between lines inside a paragraph
  paragraphGapBelow:    1, // Space below each paragraph (gap between two paragraphs)
  bodyTextColor: [17, 24, 39], // Body text colour — #111827

  // ── HEADINGS (H1, H2, H3 etc.) ────────────────────────────
  h1Size: 16,  h1LineHeight: 8,
  h2Size: 15,  h2LineHeight: 7.5,
  h3Size: 14,  h3LineHeight: 7,
  h4Size: 13,  h4LineHeight: 6.5,
  h5Size: 12,  h5LineHeight: 6,
  h6Size: 12,  h6LineHeight: 6,
  headingGapAbove: 4,  // Extra space above every heading
  headingGapBelow: 3,  // Extra space below every heading

  // ── HEADING COLOURS (hex → RGB) ───────────────────────────
  // Descending blue scale — matches academic chemistry book style (JD Lee / NCERT)
  h1Color: [11,  60, 145],  // #0b3c91 — deep navy       (chapter titles)
  h2Color: [21, 101, 192],  // #1565c0 — strong blue      (main sections)
  h3Color: [30,  64, 175],  // #1e40af — indigo-blue      (sub-sections)
  h4Color: [37,  99, 235],  // #2563eb — medium blue      (sub-topics)
  h5Color: [59, 130, 246],  // #3b82f6 — lighter blue     (minor sub-points)
  h6Color: [75, 140, 220],  // #60a5fa — softest blue     (deep nested notes)

  // ── IMAGE PLACEHOLDER BOX ─────────────────────────────────
  imageBoxHeight:  11,  // Height of the [Image: ...] box
  imageGapBelow:   20,  // Space below image box before next paragraph

  // ── TABLE COLOURS ─────────────────────────────────────────
  // Navy-blue theme — matches H1 heading colour for professional chemistry book look
  tableHeaderBg:      [11,  60, 145],  // #0b3c91 — header row background (deep navy)
  tableEvenRowBg:     [238, 242, 251], // #eef2fb — even row background (light blue-grey)
  tableOddRowBg:      [255, 255, 255], // #ffffff — odd row background (white)
  tableBorderColor:   [21, 101, 192],  // #1565c0 — outer border and row border
  tableDividerColor:  [199, 215, 245], // #c7d7f5 — inner vertical cell divider

  // ── TABLE ─────────────────────────────────────────────────
  tableCellFontSize: 10.5,  // Font size of text inside table cells
  tableRowHeight:    8,  // Height of each table row
  tableGapBelow:     10,  // Space below the whole table

  // ── LIST ITEMS (bullet points) ────────────────────────────
  listItemLineHeight: 7, // Space between lines in a bullet point
  listItemGapBelow:   4, // Space below each bullet point

  // ── BLOCKQUOTE / CODE BLOCK ───────────────────────────────
  blockquoteLineHeight: 6, // Space between lines inside a blockquote or code block
  blockquoteGapBelow:   4, // Space below a blockquote or code block

  // ── FOOTER ────────────────────────────────────────────────
  footerFontSize:  13.5, // Font size of main footer text
  footerHeight:    20,   // Height of footer bar
  footerGapAbove:  10,   // Space above footer

  // ── "YOU MAY ALSO LIKE" CARDS ─────────────────────────────
  relatedSectionGapAbove: 14, // Space above "You May Also Like" heading
  cardFontSize:  8.5,         // Font size of link text inside cards
  cardHeight:    18,          // Height of each card
  cardGap:        4,          // Gap between card rows

};
// ============================================================
//              END OF SETTINGS — DO NOT EDIT BELOW
// ============================================================


// ── Unicode Font — DejaVuSans subset, embedded directly ──
// Supports: Greek (α β Δ), subscripts (₁₂₃), arrows (→ ⇌), math symbols (° ± ×)
// No download needed. No CDN. Works offline. 100% reliable.
const DEJAVU_REGULAR = '';
const DEJAVU_BOLD    = '';

function loadUnicodeFont(pdf) {
  try {
    pdf.addFileToVFS('DejaVuSans.ttf', DEJAVU_REGULAR);
    pdf.addFont('DejaVuSans.ttf', 'DejaVuSans', 'normal');
    pdf.addFileToVFS('DejaVuSans-Bold.ttf', DEJAVU_BOLD);
    pdf.addFont('DejaVuSans-Bold.ttf', 'DejaVuSans', 'bold');
    return true;
  } catch(e) {
    console.warn('Font embed failed, using helvetica:', e.message);
    return false;
  }
}


async function generatePostPDF() {
if(!window[['_0x','4f','9d'].join('')] || !window[['_0x','4f','9d'].join('')][['Ch','em','i','str','y','Sp','ark'].join('')]) return;
  const btn = document.getElementById('pdf-btn-final');
  const postBody = document.querySelector('.post-body');
  const postTitle = document.querySelector('.post-title')
    ? document.querySelector('.post-title').innerText.trim()
    : 'Post';
  if (!postBody) return;

  // Check if font is already cached — show different message accordingly
  btn.innerHTML = '&#x23F3; Building PDF...';
  btn.disabled = true;

  try {
    const { jsPDF } = window.jspdf;
    const C = CONFIG;

    const pdf = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait', compress: true });

    const unicodeFontLoaded = loadUnicodeFont(pdf);
    const FONT = unicodeFontLoaded ? 'DejaVuSans' : 'helvetica';

    const pageW  = 210;
    const pageH  = 297;
    const printW = pageW - C.marginLeft - C.marginRight;
    let cursorY  = C.marginTop;

    // ── Helpers ──
    function checkPage(neededMM) {
      if (cursorY + neededMM > pageH - C.marginBottom) {
        pdf.addPage();
        cursorY = C.marginTop;
      }
    }

    function setFont(style) {
      // 'italic' style not available in embedded font subset — use normal instead
      pdf.setFont(FONT, (style === 'italic' && unicodeFontLoaded) ? 'normal' : style);
    }

    // ── HEADER ──
    pdf.setFillColor(248, 249, 250);
    pdf.rect(C.marginLeft, cursorY, printW, C.headerHeight, 'F');
    pdf.setDrawColor(0, 126, 101);
    pdf.setLineWidth(1.5);
    pdf.line(C.marginLeft, cursorY, C.marginLeft, cursorY + C.headerHeight);
    pdf.setLineWidth(0.2);
    pdf.setTextColor(0, 126, 101);
    setFont('bold');
    pdf.setFontSize(C.headerFontSize);
    pdf.text('Sudhir Nama | Chemistry Spark Publication', C.marginLeft + 5, cursorY + 13);
    cursorY += C.headerGapBelow;

    // ── POST TITLE ──
    pdf.setTextColor(20, 20, 20);
    setFont('bold');
    pdf.setFontSize(C.postTitleFontSize);
    const titleLines = pdf.splitTextToSize(postTitle, printW);
    const titleBlockH = titleLines.length * C.postTitleLineHeight + C.postTitleGapBelow;
    checkPage(titleBlockH);
    pdf.text(titleLines, C.marginLeft, cursorY);
    cursorY += titleBlockH;

    // ── DIVIDER ──
    pdf.setDrawColor(0, 126, 101);
    pdf.setLineWidth(0.6);
    pdf.line(C.marginLeft, cursorY, pageW - C.marginRight, cursorY);
    cursorY += C.dividerGapBelow;

    // ── HEADING SIZE ARRAYS ──
    const headingSizes = [0, C.h1Size, C.h2Size, C.h3Size, C.h4Size, C.h5Size, C.h6Size];
    const headingLineH = [0, C.h1LineHeight, C.h2LineHeight, C.h3LineHeight, C.h4LineHeight, C.h5LineHeight, C.h6LineHeight];
    // Heading colours per level (H4–H6 reuse H3 colour)
    const headingColors = [C.h1Color, C.h1Color, C.h2Color, C.h3Color, C.h4Color, C.h5Color, C.h6Color];

    function getTagLevel(tag) {
      return { H1:1, H2:2, H3:3, H4:4, H5:5, H6:6 }[tag] || 0;
    }

    let relatedLinks = [];

    // ── YOU MAY ALSO LIKE CARDS ──
    function flushRelatedCards() {
      if (!relatedLinks.length) return;
      cursorY += C.relatedSectionGapAbove;
      checkPage(10);
      setFont('bold');
      pdf.setFontSize(15);
      pdf.setTextColor(0, 126, 101);
      pdf.text('You May Also Like', C.marginLeft, cursorY);
      cursorY += 8;

      const cardW = (printW - 4) / 2;
      for (let i = 0; i < relatedLinks.length; i++) {
        const col = i % 2;
        if (col === 0) checkPage(C.cardHeight + C.cardGap);
        const x = C.marginLeft + col * (cardW + 4);
        const y = cursorY;

        pdf.setFillColor(245, 252, 250);
        pdf.roundedRect(x, y, cardW, C.cardHeight, 2, 2, 'F');
        pdf.setDrawColor(0, 126, 101);
        pdf.setLineWidth(0.4);
        pdf.roundedRect(x, y, cardW, C.cardHeight, 2, 2, 'S');
        pdf.setFillColor(0, 126, 101);
        pdf.roundedRect(x, y, 2.5, C.cardHeight, 1, 1, 'F');

        setFont('bold');
        pdf.setFontSize(C.cardFontSize);
        pdf.setTextColor(0, 90, 180);
        const linkLines = pdf.splitTextToSize(relatedLinks[i].title, cardW - 9).slice(0, 2);
        linkLines.forEach((line, li) => pdf.text(line, x + 5, y + 7 + li * 5));
        if (relatedLinks[i].url) pdf.link(x, y, cardW, C.cardHeight, { url: relatedLinks[i].url });

        // Arrow
        setFont('normal');
        pdf.setTextColor(0, 126, 101);
        pdf.setFontSize(10);
        pdf.text('\u2192', x + cardW - 7, y + C.cardHeight - 4);

        if (col === 1 || i === relatedLinks.length - 1) cursorY += C.cardHeight + C.cardGap;
      }
      relatedLinks = [];
      cursorY += 4;
    }

    // ── Shared inline segment collector ──
    // Walks ANY DOM node and returns a flat segment array: { text, bold, hl, sub, sup }
    // Called by every renderer (p, li, headings, div, span …) so sub/sup is handled
    // correctly no matter which tag it lives inside.
    // ── Universal exam-tag detector ──────────────────────────────────────────
    // Returns true for any <span> whose class list contains "exam-tag".
    // Works regardless of extra modifier classes (e.g. "exam-tag jee", "exam-tag csir").
    // All pill-rendering code calls this helper so detection is consistent everywhere.
    function isExamTagSpan(el) {
      if (!el || el.tagName !== 'SPAN') return false;
      return (el.className || '').split(/\s+/).includes('exam-tag');
    }

    // ── Universal section-tag detector ───────────────────────────────────────
    // Returns true for any <span> whose class list contains "section-tag".
    function isSectionTagSpan(el) {
      if (!el || el.tagName !== 'SPAN') return false;
      return (el.className || '').split(/\s+/).includes('section-tag');
    }

    // ── Shared pill renderer ──────────────────────────────────────────────────
    // Renders an array of labels as coloured pill badges at the current cursorY.
    // colors: array of [r,g,b] — cycled across labels.
    // Returns after advancing cursorY.
    function renderPills(labels, colors, PILL_H, PILL_PX, PILL_GAP, PILL_FS, PILL_R, ROW_GAP) {
      if (!labels.length) return;
      const ptMM = 0.3528;
      pdf.setFontSize(PILL_FS); setFont('bold');
      const pillWidths = labels.map(lbl => pdf.getStringUnitWidth(lbl) * PILL_FS * ptMM + PILL_PX * 2);
      checkPage(PILL_H + ROW_GAP + 2);
      let px = C.marginLeft;
      labels.forEach((lbl, i) => {
        const pw = pillWidths[i];
        if (px + pw > C.marginLeft + printW) { px = C.marginLeft; cursorY += PILL_H + 2; checkPage(PILL_H + ROW_GAP); }
        const [r, g, b] = colors[i % colors.length];
        pdf.setFillColor(r, g, b);
        pdf.roundedRect(px, cursorY, pw, PILL_H, PILL_R, PILL_R, 'F');
        pdf.setTextColor(255, 255, 255);
        pdf.setFontSize(PILL_FS); setFont('bold');
        pdf.text(lbl, px + PILL_PX, cursorY + PILL_H - 2.8);
        px += pw + PILL_GAP;
      });
      cursorY += PILL_H + ROW_GAP;
      pdf.setTextColor(...C.bodyTextColor); setFont('normal'); pdf.setFontSize(C.paragraphFontSize);
    }

    function collectSegments(rootNode) {
      const segs = [];
      (function walk(nd, bold, hl) {
        if (nd.nodeType === Node.TEXT_NODE) {
          const t = nd.textContent
            .replace(/[‘’ʼʹ]/g, "'")
            .replace(/[“”]/g, '"')
            .replace(/–/g, '-').replace(/—/g, '--')
            .replace(/…/g, '...').replace(/ /g, ' ');
          if (t) segs.push({ text: t, bold, hl });
          return;
        }
        if (!nd.tagName) return;
        const t = nd.tagName.toUpperCase();
        if (['SCRIPT','STYLE','IMG','SVG'].includes(t)) return;
        const b  = bold || t === 'B' || t === 'STRONG';
        const h2 = hl   || t === 'MARK' ||
          (t === 'SPAN' && nd.style &&
            (nd.style.backgroundColor !== '' || nd.style.background !== ''));
        if (t === 'SUB') {
          const txt = nd.innerText || '';
          if (txt) segs.push({ text: txt, bold: b, hl: h2, sub: true });
          return;
        }
        if (t === 'SUP') {
          const txt = nd.innerText || '';
          if (txt) segs.push({ text: txt, bold: b, hl: h2, sup: true });
          return;
        }
        Array.from(nd.childNodes).forEach(c => walk(c, b, h2));
      })(rootNode, false, false);
      return segs;
    }

    // ── Shared rich line renderer ──
    // Renders a segments array word-by-word with bold/sub/sup/highlight.
    // startX   = left edge mm   availW = available width mm
    // lineH    = line height mm gapBelow = gap after last line mm
    function renderSegments(segs, startX, availW, lineH, gapBelow) {
      if (!segs.length) return;
      const fs   = C.paragraphFontSize;
      const ptMM = 0.3528;
      const plain = segs.map(s => s.text).join('').replace(/\s+/g, ' ').trim();
      if (!plain) return;
      pdf.setFontSize(fs); setFont('normal');
      const plainLines = pdf.splitTextToSize(plain, availW);
      const totalH = plainLines.length * lineH + gapBelow;
      checkPage(totalH);

      const hasRich = segs.some(s => s.bold || s.hl || s.sub || s.sup);
      if (!hasRich) {
        pdf.setTextColor(...C.bodyTextColor);
        plainLines.forEach((line, i) => pdf.text(line, startX, cursorY + i * lineH));
        cursorY += totalH;
        return;
      }

      const words = [];
      for (const seg of segs) {
        const tokens = seg.text.split(/(\s+)/);
        for (const tok of tokens) {
          if (tok === '') continue;
          words.push({ tok, bold: seg.bold, hl: seg.hl, sub: seg.sub, sup: seg.sup });
        }
      }

      let wx = startX, wy = cursorY;
      for (const w of words) {
        const isSpace  = /^\s+$/.test(w.tok);
        const isSub    = !!w.sub;
        const isSup    = !!w.sup;
        const renderFs = (isSub || isSup) ? fs * 0.75 : fs;
        const yOff     = isSup ? -(renderFs * ptMM * 0.85)
                       : isSub  ?  (renderFs * ptMM * 0.40) : 0;
        setFont(w.bold ? 'bold' : 'normal');
        pdf.setFontSize(renderFs);
        const ww = pdf.getStringUnitWidth(w.tok) * renderFs * ptMM;
        if (wx + ww > startX + availW + 0.5) {
          if (isSpace) continue;
          wx = startX; wy += lineH;
          if (wy > 297 - C.marginBottom) { pdf.addPage(); wy = C.marginTop; }
        }
        if (isSpace) { wx += ww; continue; }
        if (w.hl) {
          pdf.setFillColor(255, 255, 0);
          pdf.rect(wx, wy - renderFs * ptMM + 0.3 + yOff, ww, renderFs * ptMM + 1, 'F');
        }
        pdf.setTextColor(...C.bodyTextColor);
        setFont(w.bold ? 'bold' : 'normal');
        pdf.setFontSize(renderFs);
        pdf.text(w.tok, wx, wy + yOff);
        wx += ww;
      }
      const richEndY  = wy + lineH + gapBelow;
      const plainEndY = cursorY + totalH;
      cursorY = Math.max(richEndY, plainEndY);
    }

    // ── BOX BODY RENDERER (NEW — does NOT touch any existing code) ──────────────
    // Renders the inner content of styled boxes (info/tip/warning/highlight/tooltip)
    // using the rich segment-based engine so <sub>, <sup>, bold, and highlighted
    // text inside boxes appear correctly in the PDF — exactly as they do in
    // paragraphs and table cells.
    //
    // Parameters:
    //   boxNode   — the DIV element that was detected as a box
    //   headingEl — the heading element to skip (already drawn as the box title),
    //               or null if there is no heading
    //   startX    — left margin (mm)
    //   availW    — available text width (mm)
    //   textClr   — [r, g, b] text colour for body lines
    //   startY    — the Y position (mm) where body text should begin
    //
    // Returns the new cursorY after all body content has been rendered.
    function renderBoxBody(boxNode, headingEl, startX, availW, textClr, startY) {
      // Walk direct children of the box node and collect renderable nodes,
      // skipping the heading element (already drawn) and SCRIPT/STYLE nodes.
      const childNodes = Array.from(boxNode.childNodes);
      let localY = startY;

      // Helper: render one set of segments at localY and advance localY
      function renderLine(segs) {
        if (!segs.length) return;
        const plain = segs.map(s => s.text).join('').replace(/\s+/g, ' ').trim();
        if (!plain) return;
        const fs   = C.paragraphFontSize;
        const ptMM = 0.3528;
        pdf.setFontSize(fs); setFont('normal');
        const splitLines = pdf.splitTextToSize(plain, availW);
        const totalH = splitLines.length * C.paragraphLineHeight + C.paragraphGapBelow;
        // page-break guard
        if (localY + totalH > 297 - C.marginBottom) { pdf.addPage(); localY = C.marginTop; }

        const hasRich = segs.some(s => s.bold || s.hl || s.sub || s.sup);
        pdf.setTextColor(...textClr);
        if (!hasRich) {
          splitLines.forEach((line, i) => pdf.text(line, startX, localY + i * C.paragraphLineHeight));
          localY += totalH;
          return;
        }
        // Rich word-by-word path (bold / highlight / sub / sup)
        const words = [];
        for (const seg of segs) {
          const tokens = seg.text.split(/(\s+)/);
          for (const tok of tokens) {
            if (tok !== '') words.push({ tok, bold: seg.bold, hl: seg.hl, sub: seg.sub, sup: seg.sup });
          }
        }
        let wx = startX, wy = localY;
        for (const w of words) {
          const isSpace  = /^\s+$/.test(w.tok);
          const renderFs = (w.sub || w.sup) ? fs * 0.75 : fs;
          const yOff     = w.sup ? -(renderFs * ptMM * 0.85) : w.sub ? (renderFs * ptMM * 0.40) : 0;
          setFont(w.bold ? 'bold' : 'normal');
          pdf.setFontSize(renderFs);
          const ww = pdf.getStringUnitWidth(w.tok) * renderFs * ptMM;
          if (wx + ww > startX + availW + 0.5) {
            if (isSpace) continue;
            wx = startX; wy += C.paragraphLineHeight;
            if (wy > 297 - C.marginBottom) { pdf.addPage(); wy = C.marginTop; }
          }
          if (isSpace) { wx += ww; continue; }
          if (w.hl) {
            pdf.setFillColor(255, 255, 0);
            pdf.rect(wx, wy - renderFs * ptMM + 0.3 + yOff, ww, renderFs * ptMM + 1, 'F');
          }
          pdf.setTextColor(...textClr);
          setFont(w.bold ? 'bold' : 'normal');
          pdf.setFontSize(renderFs);
          pdf.text(w.tok, wx, wy + yOff);
          wx += ww;
        }
        localY = Math.max(wy + C.paragraphLineHeight + C.paragraphGapBelow, localY + totalH);
      }

      // Walk through child nodes of the box, grouping inline nodes between BRs/blocks
      let pendingNodes = [];
      const flushPending = () => {
        if (!pendingNodes.length) return;
        const segs = [];
        pendingNodes.forEach(n => segs.push(...collectSegments(n)));
        renderLine(segs);
        pendingNodes = [];
      };

      for (const child of childNodes) {
        // Skip the heading that is already rendered as the box title
        if (headingEl && child === headingEl) continue;
        if (child.nodeType === Node.TEXT_NODE) {
          // Wrap bare text in a temporary element so collectSegments can handle it
          if (child.textContent.replace(/\s+/, '').length > 0) pendingNodes.push(child);
          continue;
        }
        if (child.nodeType !== Node.ELEMENT_NODE) continue;
        const ct = child.tagName.toUpperCase();
        if (['SCRIPT', 'STYLE'].includes(ct)) continue;
        if (ct === 'BR') { flushPending(); continue; }
        // Block-level children (P, LI, UL, OL, DIV …) — flush pending, then render block
        const isBlock = ['P','DIV','UL','OL','LI','H1','H2','H3','H4','H5','H6','BLOCKQUOTE','PRE'].includes(ct);
        if (isBlock) {
          flushPending();
          // For UL/OL recurse into LI children
          if (ct === 'UL' || ct === 'OL') {
            Array.from(child.querySelectorAll('li')).forEach(li => {
              const liSegs = collectSegments(li);
              renderLine(liSegs);
            });
          } else {
            const blockSegs = collectSegments(child);
            renderLine(blockSegs);
          }
        } else {
          // Inline element (SPAN, B, STRONG, SUB, SUP, EM, etc.)
          pendingNodes.push(child);
        }
      }
      flushPending();
      return localY;
    }
    // ── END renderBoxBody ───────────────────────────────────────────────────────

    // ── BOX BODY HEIGHT MEASURER ─────────────────────────────────────────────
    // Mirrors renderBoxBody exactly — same DOM walk, same collectSegments, same
    // splitTextToSize — but ONLY measures height without drawing anything.
    // This guarantees the pre-drawn border rectangle always matches actual content.
    function measureBoxBody(boxNode, headingEl, availW) {
      const childNodes = Array.from(boxNode.childNodes);
      let measuredH = 0;

      function measureLine(segs) {
        if (!segs.length) return;
        const plain = segs.map(s => s.text).join('').replace(/\s+/g, ' ').trim();
        if (!plain) return;
        pdf.setFontSize(C.paragraphFontSize); setFont('normal');
        const splitLines = pdf.splitTextToSize(plain, availW);
        measuredH += splitLines.length * C.paragraphLineHeight + C.paragraphGapBelow;
      }

      let pendingNodes = [];
      const flushPending = () => {
        if (!pendingNodes.length) return;
        const segs = [];
        pendingNodes.forEach(n => segs.push(...collectSegments(n)));
        measureLine(segs);
        pendingNodes = [];
      };

      for (const child of childNodes) {
        if (headingEl && child === headingEl) continue;
        if (child.nodeType === Node.TEXT_NODE) {
          if (child.textContent.replace(/\s+/, '').length > 0) pendingNodes.push(child);
          continue;
        }
        if (child.nodeType !== Node.ELEMENT_NODE) continue;
        const ct = child.tagName.toUpperCase();
        if (['SCRIPT', 'STYLE'].includes(ct)) continue;
        if (ct === 'BR') { flushPending(); continue; }
        const isBlock = ['P','DIV','UL','OL','LI','H1','H2','H3','H4','H5','H6','BLOCKQUOTE','PRE'].includes(ct);
        if (isBlock) {
          flushPending();
          if (ct === 'UL' || ct === 'OL') {
            Array.from(child.querySelectorAll('li')).forEach(li => {
              measureLine(collectSegments(li));
            });
          } else {
            measureLine(collectSegments(child));
          }
        } else {
          pendingNodes.push(child);
        }
      }
      flushPending();
      return measuredH;
    }
    // ── END measureBoxBody ───────────────────────────────────────────────────

    // ── Text extractor: returns plain text for all nodes ──
    // SUB/SUP return their raw text — the paragraph rich renderer handles
    // visual sizing and positioning, so no unicode conversion is done here.
    // Unicode sub/superscripts typed directly in the article are preserved as-is.
    function getNodeText(node) {
      if (node.nodeType === Node.TEXT_NODE) return node.textContent;
      const tag = node.tagName ? node.tagName.toUpperCase() : '';
      if (['SCRIPT','STYLE'].includes(tag)) return '';

      // SUB/SUP: return plain text — the rich paragraph renderer handles visual sizing
      if (tag === 'SUB' || tag === 'SUP') {
        return node.innerText || '';
      }

      // For all other nodes, recurse and join child text
      const raw = Array.from(node.childNodes).map(getNodeText).join('');
      // Normalize Unicode punctuation that the embedded font subset may not contain:
      // smart apostrophes/quotes → ASCII equivalents, dashes → hyphens/dashes
      return raw
        .replace(/[\u2018\u2019\u02BC\u02B9]/g, "'")   // ' ' ʼ ʹ  → '
        .replace(/[\u201C\u201D]/g, '"')                // " "       → "
        .replace(/\u2013/g, '-')                        // en dash   → -
        .replace(/\u2014/g, '--')                       // em dash   → --
        .replace(/\u2026/g, '...')                      // ellipsis  → ...
        .replace(/\u00A0/g, ' ');                       // nbsp      → space
    }

    // ── Image helpers — shared by IMG and SVG handlers ──
    async function tryLoadImg(imgEl, url) {
      return new Promise((resolve) => {
        let settled = false;
        function finish(ok) { if (!settled) { settled = true; resolve(ok); } }
        imgEl.onload  = () => finish(true);
        imgEl.onerror = () => finish(false);
        imgEl.crossOrigin = 'anonymous';
        imgEl.src = url;
        setTimeout(() => finish(false), 25000);
      });
    }

    function paintImage(imgEl) {
      const ow = imgEl.naturalWidth, oh = imgEl.naturalHeight;
      if (!ow || !oh) return false;
      try {
        const cvs = document.createElement('canvas');
        cvs.width = ow; cvs.height = oh;
        cvs.getContext('2d').drawImage(imgEl, 0, 0, ow, oh);
        const data = cvs.toDataURL('image/jpeg', 0.88);
        if (data.length < 100) return false;
        const pw = printW;
        const ph = Math.min(oh * (printW / ow), 200);
        checkPage(ph + 6);
        pdf.addImage(data, 'JPEG', C.marginLeft, cursorY, pw, ph);
        cursorY += ph + 12;
        return true;
      } catch(e) { return false; }
    }

    // ── DOM WALKER ──
    async function processNode(node) {
      if (node.nodeType === Node.TEXT_NODE) return;

      const tag = node.tagName ? node.tagName.toUpperCase() : '';

      // Skip non-content tags
      if (['SCRIPT','STYLE','BUTTON','IFRAME','NAV','NOSCRIPT'].includes(tag)) return;

      // ── "You May Also Like" detection ──
      if (tag === 'DIV' || tag === 'SECTION') {
        const headingEl = node.querySelector('h2,h3,h4,h5');
        const headingText = headingEl ? headingEl.innerText.trim().toLowerCase() : '';
        if (
          headingText.includes('you may also like') ||
          headingText.includes('related post') ||
          headingText.includes('popular post')
        ) {
          Array.from(node.querySelectorAll('a[href]')).forEach(a => {
            const title = a.innerText.trim();
            const url   = a.href;
            if (title && url && url.startsWith('http') && !relatedLinks.find(r => r.url === url))
              relatedLinks.push({ title, url });
          });
          if (relatedLinks.length) flushRelatedCards();
          return;
        }
      }

      // ── Headings — rich render so sub/sup inside headings works ──
      if (getTagLevel(tag) > 0) {
        const level = getTagLevel(tag);
        const fs = headingSizes[level];
        const lh = headingLineH[level];
        const ptMM = 0.3528;

        // ── Detect exam-tag spans inside this heading ──────────────────────
        // If the heading contains <span class="tag-badge"> or similar, we:
        // 1. Render heading text WITHOUT those spans
        // 2. Render the span content as pill badges below the heading
        const examSpanEls = Array.from(node.querySelectorAll('span')).filter(isExamTagSpan);

        // Build a version of the heading with exam spans removed
        const headingClone = node.cloneNode(true);
        Array.from(headingClone.querySelectorAll('span')).forEach(s => {
          if (isExamTagSpan(s)) s.parentNode.removeChild(s);
        });

        // Collect segments from the cleaned heading (no exam spans)
        const hSegs = collectSegments(headingClone);

        // Render the heading text if any remains
        const plain = hSegs.map(s => s.text).join('').replace(/\s+/g, ' ').trim();
        if (plain) {
          pdf.setFontSize(fs); setFont('bold');
          const plainLines = pdf.splitTextToSize(plain, printW);
          const totalH = plainLines.length * lh + C.headingGapBelow;
          checkPage(totalH + C.headingGapAbove + 3);
          cursorY += C.headingGapAbove;
          const hasRich = hSegs.some(s => s.sub || s.sup);
          if (!hasRich) {
            pdf.setTextColor(...headingColors[level]);
            pdf.text(plainLines, C.marginLeft, cursorY);
            cursorY += totalH;
          } else {
            // Rich path: word-by-word for sub/sup
            const hWords = [];
            for (const seg of hSegs) {
              const tokens = seg.text.split(/(\s+)/);
              for (const tok of tokens) { if (tok !== '') hWords.push({ tok, sub: seg.sub, sup: seg.sup }); }
            }
            let wx = C.marginLeft, wy = cursorY;
            for (const w of hWords) {
              const isSpace  = /^\s+$/.test(w.tok);
              const renderFs = (w.sub || w.sup) ? fs * 0.75 : fs;
              const yOff     = w.sup ? -(renderFs * ptMM * 0.85) : w.sub ? (renderFs * ptMM * 0.40) : 0;
              setFont('bold');
              pdf.setFontSize(renderFs);
              const ww = pdf.getStringUnitWidth(w.tok) * renderFs * ptMM;
              if (wx + ww > C.marginLeft + printW + 0.5) {
                if (isSpace) continue;
                wx = C.marginLeft; wy += lh;
                if (wy > 297 - C.marginBottom) { pdf.addPage(); wy = C.marginTop; }
              }
              if (isSpace) { wx += ww; continue; }
              pdf.setTextColor(...headingColors[level]);
              pdf.text(w.tok, wx, wy + yOff);
              wx += ww;
            }
            cursorY = Math.max(wy + lh + C.headingGapBelow, cursorY + totalH);
          }
        }

        // ── Render exam-tag spans as pill badges below the heading ──────────
        if (examSpanEls.length > 0) {
          const PILL_H   = 8;     // pill height mm
          const PILL_PX  = 4;     // horizontal padding mm
          const PILL_GAP = 2.5;   // gap between pills mm
          const PILL_FS  = 9;     // font size pt
          const PILL_R   = 2;     // corner radius mm
          const ROW_GAP  = 8;     // space below pills mm
          cursorY -= 2;           // reduce space above pills

          // Collect all labels — support both single pipe-separated span
          // and multiple individual spans
          let labels = [];
          if (examSpanEls.length === 1) {
            labels = (examSpanEls[0].textContent || '')
              .split('|').map(s => s.trim()).filter(Boolean);
          } else {
            labels = examSpanEls
              .map(s => (s.textContent || '').trim()).filter(Boolean);
          }

          if (labels.length) {
            pdf.setFontSize(PILL_FS);
            setFont('bold');
            const pillWidths = labels.map(
              lbl => pdf.getStringUnitWidth(lbl) * PILL_FS * ptMM + PILL_PX * 2
            );
            checkPage(PILL_H + ROW_GAP + 2);
            let px = C.marginLeft;
            const colors = [
              [0, 110, 90], [50, 80, 110], [80, 100, 40],
              [120, 60, 20], [60, 60, 130], [20, 100, 100],
            ];
            labels.forEach((lbl, i) => {
              const pw = pillWidths[i];
              if (px + pw > C.marginLeft + printW) {
                px = C.marginLeft;
                cursorY += PILL_H + 2;
                checkPage(PILL_H + ROW_GAP);
              }
              const [r, g, b] = colors[i % colors.length];
              pdf.setFillColor(r, g, b);
              pdf.roundedRect(px, cursorY, pw, PILL_H, PILL_R, PILL_R, 'F');
              pdf.setTextColor(255, 255, 255);
              pdf.setFontSize(PILL_FS);
              setFont('bold');
              pdf.text(lbl, px + PILL_PX, cursorY + PILL_H - 2.8);
              px += pw + PILL_GAP;
            });
            cursorY += PILL_H + ROW_GAP;
            pdf.setTextColor(...C.bodyTextColor);
            setFont('normal');
            pdf.setFontSize(C.paragraphFontSize);
          }
        }

        return;
      }

      // ── Images — render actual image into PDF ──
      if (tag === 'IMG') {
        const src = node.getAttribute('data-src') || node.getAttribute('src') || node.src || '';
        const alt = (node.getAttribute('alt') || '').trim();
        if (!src || src.startsWith('data:') && src.length < 100) return; // skip tiny placeholders

        // Build candidate URLs in priority order:
        // 1. Blogger CDN size-token swap: replace /sXXXX/ with /s800/ — same origin, no CORS
        // 2. wsrv.nl proxy — converts webp/avif → jpeg and bypasses CORS
        // 3. Original src as last resort
        const candidates = [];
        const bloggerResized = src.replace(/\/(s|w)\d+(-[a-z]+)*\//i, '/s800/');
        if (bloggerResized !== src) candidates.push(bloggerResized);
        candidates.push('https://wsrv.nl/?url=' + encodeURIComponent(src) + '&output=jpg&w=750&q=88');
        if (!candidates.includes(src)) candidates.push(src);

        let added = false;
        for (const url of candidates) {
          if (added) break;
          try {
            const img = new Image();
            const ok = await tryLoadImg(img, url);
            if (ok && img.naturalWidth > 0) added = paintImage(img);
          } catch(e) { /* try next */ }
        }

        if (!added) {
          // Fallback placeholder box
          const boxH = C.imageBoxHeight;
          checkPage(boxH + 4);
          pdf.setFillColor(237, 247, 244);
          pdf.roundedRect(C.marginLeft, cursorY, printW, boxH, 2, 2, 'F');
          pdf.setDrawColor(0, 126, 101); pdf.setLineWidth(0.3);
          pdf.roundedRect(C.marginLeft, cursorY, printW, boxH, 2, 2, 'S');
          pdf.setTextColor(80, 80, 80); setFont('normal'); pdf.setFontSize(9);
          pdf.text('[Image: ' + (alt || src.split('/').pop().split('?')[0] || 'image') + ']', C.marginLeft + 4, cursorY + 7.5);
          cursorY += C.imageGapBelow;
        }
        return;
      }

      // ── Inline SVG — canvas-first renderer: guaranteed to render any SVG ──
      if (tag === 'SVG') {
        // ① Resolve dimensions (shared by both paths)
        // Priority: viewBox (most reliable) → rendered bbox → explicit px attr
        // Never use percentage attr values — parseFloat("100%") = 100 which is wrong
        let sw = 0, sh = 0;
        const vb = node.getAttribute('viewBox');
        if (vb) {
          const vbP = vb.trim().split(/[\s,]+/);
          if (vbP.length >= 4) { sw = parseFloat(vbP[2]); sh = parseFloat(vbP[3]); }
        }
        if (!sw || !sh) {
          const bbox = node.getBoundingClientRect();
          if (bbox.width > 0 && bbox.height > 0) { sw = bbox.width; sh = bbox.height; }
        }
        if (!sw || !sh) {
          const wa = node.getAttribute('width'),  ha = node.getAttribute('height');
          const wp = parseFloat(wa), hp = parseFloat(ha);
          // Only use attr if it is a plain number (not a percentage)
          if (wa && !wa.includes('%') && wp > 0) sw = wp;
          if (ha && !ha.includes('%') && hp > 0) sh = hp;
        }
        sw = Math.round(sw) || 640; sh = Math.round(sh) || 480;
        const pw = printW;
        // ph: scale to fit print width, preserving aspect ratio — no hard cap so
        // tall SVGs (e.g. flowcharts) are never clipped regardless of their height
        const ph = sh * (printW / sw);

        // ② Detect whether the SVG embeds raster images — if so, skip svg2pdf
        const hasEmbeddedImage = node.querySelector('image') !== null;

        // ③ Detect unicode subscripts/superscripts — svg2pdf cannot render these
        const svgText = node.textContent || '';
        const hasUnicodeSubSuper = /[₀₁₂₃₄₅₆₇₈₉ₙₐₑₒₓₔₕₖₗₘₚₛₜ₍₎₊₋₌⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻⁼⁽⁾ⁿ]/.test(svgText);

        // ④ svg2pdf path — only for pure vector SVGs with no known problem characters
        if (!hasEmbeddedImage && !hasUnicodeSubSuper && typeof window.svg2pdf === 'function') {
          try {
            const svgClone = node.cloneNode(true);
            if (!svgClone.getAttribute('xmlns'))
              svgClone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
            svgClone.setAttribute('width',  sw);
            svgClone.setAttribute('height', sh);
            // svg2pdf needs a live DOM element — attach off-screen, convert, detach
            svgClone.style.cssText = 'position:absolute;left:-9999px;top:-9999px;';
            document.body.appendChild(svgClone);
            try {
              checkPage(ph + 6);
              await window.svg2pdf(svgClone, pdf, {
                x: C.marginLeft, y: cursorY, width: pw, height: ph
              });
              cursorY += ph + 6;
            } finally {
              document.body.removeChild(svgClone);
            }
            return; // done — no canvas needed
          } catch(svgPdfErr) {
            // svg2pdf failed — fall through to canvas which handles everything
          }
        }

        // ⑤ Canvas fallback — handles ALL SVGs: raster-embedded, unicode text,
        //    any size/shape, and anything svg2pdf cannot process.
        //    After placing the raster image, invisible selectable text is overlaid
        //    so SVG text remains searchable and copy-pasteable in the PDF.
        try {
          const svgClone = node.cloneNode(true);
          if (!svgClone.getAttribute('xmlns'))
            svgClone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
          if (!svgClone.getAttribute('xmlns:xlink'))
            svgClone.setAttribute('xmlns:xlink', 'http://www.w3.org/1999/xlink');
          svgClone.setAttribute('width',  sw);
          svgClone.setAttribute('height', sh);

          const svgStr  = new XMLSerializer().serializeToString(svgClone);
          const svgBlob = new Blob([svgStr], { type: 'image/svg+xml;charset=utf-8' });
          const svgUrl  = URL.createObjectURL(svgBlob);
          const svgImg  = new Image();
          svgImg.width  = sw; svgImg.height = sh;
          const svgOk   = await tryLoadImg(svgImg, svgUrl);
          URL.revokeObjectURL(svgUrl);
          if (!svgOk || !svgImg.naturalWidth) return;

          const SCALE = 3;
          const cvs   = document.createElement('canvas');
          cvs.width   = sw * SCALE; cvs.height = sh * SCALE;
          const ctx   = cvs.getContext('2d');
          ctx.scale(SCALE, SCALE);
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, sw, sh);
          ctx.drawImage(svgImg, 0, 0, sw, sh);

          const data = cvs.toDataURL('image/png');
          if (!data || data.length < 200) return;
          checkPage(ph + 6);
          pdf.addImage(data, 'PNG', C.marginLeft, cursorY, pw, ph);

          // ── Invisible selectable text overlay ──────────────────────────────
          // Walk every <text> element in the SVG and place a transparent jsPDF
          // text run at the same relative position so the PDF is searchable and
          // copy-pasteable even though the visual is a raster image.
          const scaleX = pw / sw;   // mm per SVG user-unit (horizontal)
          const scaleY = ph / sh;   // mm per SVG user-unit (vertical)
          const imageTop = cursorY; // cursorY before we advance it

          const textEls = node.querySelectorAll('text, tspan');
          if (textEls.length > 0) {
            // Gather unique text elements (skip tspan children whose parent <text>
            // we will already handle via combined innerText).
            const seen = new Set();
            textEls.forEach(el => {
              if (el.tagName.toLowerCase() === 'tspan') {
                // Only process tspan when it has its own x/y (independent position)
                if (!el.hasAttribute('x') && !el.hasAttribute('y')) return;
              }
              const content = (el.textContent || '').trim();
              if (!content) return;

              // Get the element's bounding box in SVG coordinates
              let ex = 0, ey = 0, efs = 12;
              try {
                const bbox = el.getBoundingClientRect();
                const svgRect = node.getBoundingClientRect();
                if (bbox.width > 0) {
                  ex = bbox.left - svgRect.left;
                  ey = bbox.top  - svgRect.top + bbox.height * 0.8; // baseline approx
                }
              } catch(e) { /* use defaults */ }

              // Fall back to x/y attributes if getBoundingClientRect gave zeros
              if (ex === 0 && ey === 0) {
                ex = parseFloat(el.getAttribute('x') || el.getAttribute('cx') || '0');
                ey = parseFloat(el.getAttribute('y') || el.getAttribute('cy') || '0');
              }

              // Estimate font size from SVG font-size attribute / computed style
              try {
                const fsAttr = el.getAttribute('font-size') ||
                               el.style.fontSize ||
                               window.getComputedStyle(el).fontSize;
                if (fsAttr) {
                  const fsPx = parseFloat(fsAttr);
                  if (fsPx > 0) efs = fsPx;
                }
              } catch(e) { /* keep default */ }

              // Convert SVG px font-size → approximate PDF pt size using scale
              const efsPt = Math.max(4, Math.round(efs * scaleY * 2.835));

              // Convert SVG coordinates → PDF mm relative to image origin
              const pdfX = C.marginLeft + ex * scaleX;
              const pdfY = imageTop     + ey * scaleY;

              // Deduplicate: same text at same rounded position → skip
              const key = Math.round(pdfX) + '|' + Math.round(pdfY) + '|' + content;
              if (seen.has(key)) return;
              seen.add(key);

              // Place invisible text: render colour = white with 0 opacity trick
              // jsPDF doesn't support true transparency on text, so we use
              // setTextColor with the background colour (white) and rely on the
              // fact that the raster image is drawn BELOW — the white text is
              // invisible but the PDF text layer is still present for search/copy.
              const prevColor = pdf.getTextColor();
              pdf.setTextColor(255, 255, 255); // white = invisible over white page
              pdf.setFontSize(efsPt);
              setFont('normal');
              try {
                pdf.text(content, pdfX, pdfY, { renderingMode: 'invisible' });
              } catch(noInvisible) {
                // Fallback: older jsPDF versions don't support renderingMode
                // Use white text at 1% opacity — still functionally invisible
                pdf.text(content, pdfX, pdfY);
              }
              // Restore previous colour so subsequent content is unaffected
              pdf.setTextColor(prevColor);
            });
            // Restore normal font size for subsequent content
            pdf.setFontSize(C.paragraphFontSize);
            setFont('normal');
            pdf.setTextColor(...C.bodyTextColor);
          }
          // ── End invisible text overlay ─────────────────────────────────────

          cursorY += ph + 12;
        } catch(svgErr) { /* canvas render also failed — skip silently */ }
        return;
      }

      // ── FIGURE / A — always recurse (they wrap images) ──
      if (tag === 'FIGURE' || tag === 'A') {
        for (const c of Array.from(node.childNodes)) { await processNode(c); }
        return;
      }

      // ── Tables — with dynamic row height to show full cell content ──
      if (tag === 'TABLE') {
        const rows = Array.from(node.querySelectorAll('tr'));
        if (!rows.length) return;
        const numCols = Math.max(...rows.map(r => r.querySelectorAll('td,th').length));
        if (!numCols) return;
        const cellLineH = C.tableCellFontSize * 0.3528 * 1.55; // pt->mm with leading
        const cellPadT  = 3;  // top padding inside cell mm
        const cellPadB  = 3;  // bottom padding inside cell mm
        const ptMM      = 0.3528;

        // ── Smart column widths ──────────────────────────────────────────────
        // Scan every cell using the correct font (bold for headers, normal for body).
        // This ensures header text like "Group Resemblance" is never measured too
        // narrow. Each column gets a guaranteed minimum; the rest is split by content.
        const colNatW = Array(numCols).fill(0);
        rows.forEach((row, ri) => {
          const isHdr = Array.from(row.querySelectorAll('td,th')).some(c => c.tagName === 'TH') || ri === 0;
          Array.from(row.querySelectorAll('td,th')).forEach((cell, ci) => {
            if (ci >= numCols) return;
            const txt = (cell.innerText || '').replace(/\s+/g, ' ').trim();
            pdf.setFontSize(C.tableCellFontSize);
            setFont(isHdr ? 'bold' : 'normal');
            const w = pdf.getStringUnitWidth(txt) * C.tableCellFontSize * ptMM + 4; // +4 for padding
            if (w > colNatW[ci]) colNatW[ci] = w;
          });
        });
        const natTotal = colNatW.reduce((a, b) => a + b, 0) || 1;
        // Minimum 14 mm per column; spare space shared proportionally by content width
        const minW  = 14;
        const spare = Math.max(0, printW - numCols * minW);
        const colWidths = colNatW.map(w => minW + spare * (w / natTotal));
        // Normalise to exactly printW
        const wTot = colWidths.reduce((a, b) => a + b, 0);
        colWidths.forEach((w, i) => { colWidths[i] = w * (printW / wTot); });
        // Helper: x-position of column ci
        const colX = ci => C.marginLeft + colWidths.slice(0, ci).reduce((a, b) => a + b, 0);

        cursorY += 3;

        // Pill constants (reused for table cell pill rendering)
        const TPILL_H   = 7;    // pill height mm
        const TPILL_PX  = 3;    // horizontal padding mm
        const TPILL_GAP = 2;    // gap between pills mm
        const TPILL_FS  = 8.5;  // font size pt
        const TPILL_R   = 1.8;  // corner radius mm
        const TPILL_COLORS = [
          [0,110,90],[50,80,110],[80,100,40],[120,60,20],[60,60,130],[20,100,100],
        ];

        // Helper: measure how tall pill rows will be for a given cell and column width
        function measureCellPills(labels, cellW) {
          pdf.setFontSize(TPILL_FS); setFont('bold');
          let px = 0, rows = 1;
          labels.forEach(lbl => {
            const pw = pdf.getStringUnitWidth(lbl) * TPILL_FS * ptMM + TPILL_PX * 2;
            if (px > 0 && px + pw > cellW - 4) { rows++; px = 0; }
            px += pw + TPILL_GAP;
          });
          return rows * (TPILL_H + 2);
        }

        rows.forEach((row, ri) => {
          const cells    = Array.from(row.querySelectorAll('td,th'));
          const isHeader = cells.some(c => c.tagName === 'TH') || ri === 0;

          // Detect which cells are exam-tag pill cells
          const cellExamLabels = cells.map(cell => {
            const examSpans = Array.from(cell.querySelectorAll('span')).filter(isExamTagSpan);
            if (!examSpans.length) return null;
            return examSpans.map(s => (s.textContent || '').trim()).filter(Boolean);
          });

          // Pre-calculate wrapped lines per cell using correct font + correct column width
          pdf.setFontSize(C.tableCellFontSize);
          const cellSegs  = cells.map(cell => collectSegments(cell));
          const cellLines = cellSegs.map((segs, ci) => {
            if (cellExamLabels[ci]) return [' ']; // pill cell — height handled separately
            const plain = segs.map(s => s.text).join('').replace(/\s+/g, ' ').trim();
            setFont(isHeader ? 'bold' : 'normal');
            return pdf.splitTextToSize(plain || ' ', colWidths[ci] - 4);
          });

          // Row height: max of text-line height and pill height across all cells
          const textRowH = Math.max(1, ...cellLines.map(l => l.length)) * cellLineH + cellPadT + cellPadB;
          const pillRowH = Math.max(0, ...cells.map((cell, ci) => {
            if (!cellExamLabels[ci]) return 0;
            return measureCellPills(cellExamLabels[ci], colWidths[ci]) + cellPadT + cellPadB;
          }));
          const rowH = Math.max(textRowH, pillRowH);

          checkPage(rowH + 2);

          // Draw row background
          const fillColor = isHeader ? C.tableHeaderBg : (ri % 2 === 0 ? C.tableOddRowBg : C.tableEvenRowBg);
          pdf.setFillColor(...fillColor);
          pdf.rect(C.marginLeft, cursorY, printW, rowH, 'F');
          pdf.setDrawColor(...C.tableBorderColor);
          pdf.setLineWidth(0.3);
          pdf.rect(C.marginLeft, cursorY, printW, rowH, 'S');

          // Draw each cell — pills for exam-tag cells, rich text for others
          cells.forEach((cell, ci) => {
            const x = colX(ci);
            if (ci > 0) {
              pdf.setDrawColor(...C.tableDividerColor);
              pdf.setLineWidth(0.2);
              pdf.line(x, cursorY, x, cursorY + rowH);
            }

            // ── Exam-tag pill cell ──
            if (cellExamLabels[ci]) {
              const labels = cellExamLabels[ci];
              pdf.setFontSize(TPILL_FS); setFont('bold');
              let px = x + 2;
              let py = cursorY + cellPadT;
              const cellRight = x + colWidths[ci] - 2;
              labels.forEach((lbl, i) => {
                const pw = pdf.getStringUnitWidth(lbl) * TPILL_FS * ptMM + TPILL_PX * 2;
                if (px > x + 2 && px + pw > cellRight) { px = x + 2; py += TPILL_H + 2; }
                const [r, g, b] = TPILL_COLORS[i % TPILL_COLORS.length];
                pdf.setFillColor(r, g, b);
                pdf.roundedRect(px, py, pw, TPILL_H, TPILL_R, TPILL_R, 'F');
                pdf.setTextColor(255, 255, 255);
                pdf.setFontSize(TPILL_FS); setFont('bold');
                pdf.text(lbl, px + TPILL_PX, py + TPILL_H - 2.3);
                px += pw + TPILL_GAP;
              });
              pdf.setTextColor(30, 30, 30); setFont('normal'); pdf.setFontSize(C.tableCellFontSize);
              return;
            }

            // ── Normal text cell ──
            const segs = cellSegs[ci];
            const fs   = C.tableCellFontSize;
            const hasRich = segs.some(s => s.sub || s.sup);
            if (!hasRich) {
              // Fast path — plain text, no sub/sup
              pdf.setFontSize(fs);
              if (isHeader) { pdf.setTextColor(255,255,255); setFont('bold'); }
              else          { pdf.setTextColor(30,30,30);    setFont('normal'); }
              cellLines[ci].forEach((line, li) => {
                pdf.text(line, x + 2, cursorY + cellPadT + (li + 1) * cellLineH);
              });
            } else {
              // Rich path — word-by-word for sub/sup inside cells
              const cWords = [];
              for (const seg of segs) {
                const tokens = seg.text.split(/(\s+)/);
                for (const tok of tokens) { if (tok !== '') cWords.push({ tok, bold: seg.bold, sub: seg.sub, sup: seg.sup }); }
              }
              let wx = x + 2;
              let wy = cursorY + cellPadT + cellLineH;
              const cellRight = x + colWidths[ci] - 2;
              for (const w of cWords) {
                const isSpace  = /^\s+$/.test(w.tok);
                const renderFs = (w.sub || w.sup) ? fs * 0.75 : fs;
                const yOff     = w.sup ? -(renderFs * ptMM * 0.85) : w.sub ? (renderFs * ptMM * 0.40) : 0;
                if (isHeader) { setFont('bold'); pdf.setTextColor(255,255,255); }
                else          { setFont(w.bold ? 'bold' : 'normal'); pdf.setTextColor(30,30,30); }
                pdf.setFontSize(renderFs);
                const ww = pdf.getStringUnitWidth(w.tok) * renderFs * ptMM;
                if (wx + ww > cellRight + 0.5) {
                  if (isSpace) continue;
                  wx = x + 2; wy += cellLineH;
                }
                if (isSpace) { wx += ww; continue; }
                pdf.text(w.tok, wx, wy + yOff);
                wx += ww;
              }
            }
          });

          cursorY += rowH;
        });
        cursorY += C.tableGapBelow;
        return;
      }

      // ── PRE / CODE blocks (hybrid font: Courier monospace) ──
      if (tag === 'PRE' || tag === 'CODE') {
        const text = node.innerText.trim();
        if (!text) return;
        pdf.setFont('Courier', 'normal'); // Roboto Mono style — built-in monospace
        pdf.setFontSize(C.paragraphFontSize - 1);
        pdf.setTextColor(20, 20, 20);
        const lines = pdf.splitTextToSize(text, printW - 10);
        const h = lines.length * C.blockquoteLineHeight + 8;
        checkPage(h + 2);
        pdf.setFillColor(240, 248, 245);
        pdf.rect(C.marginLeft, cursorY, printW, h, 'F');
        pdf.setFillColor(0, 126, 101);
        pdf.rect(C.marginLeft, cursorY, 3, h, 'F');
        pdf.setDrawColor(0, 126, 101);
        pdf.setLineWidth(0.3);
        pdf.rect(C.marginLeft, cursorY, printW, h, 'S');
        pdf.text(lines, C.marginLeft + 6, cursorY + 6);
        cursorY += h + C.blockquoteGapBelow;
        return;
      }

      // ── BLOCKQUOTE ──
      if (tag === 'BLOCKQUOTE') {
        const text = getNodeText(node).trim().replace(/\s+/g, ' ');
        if (!text) return;
        setFont('normal');
        pdf.setFontSize(C.paragraphFontSize);
        const lines = pdf.splitTextToSize(text, printW - 10);
        const h = lines.length * C.blockquoteLineHeight + 6;
        checkPage(h + 2);
        pdf.setFillColor(237, 247, 244);
        pdf.rect(C.marginLeft, cursorY, printW, h, 'F');
        pdf.setFillColor(0, 126, 101);
        pdf.rect(C.marginLeft, cursorY, 3, h, 'F');
        pdf.setTextColor(60, 60, 60);
        pdf.text(lines, C.marginLeft + 6, cursorY + 5);
        cursorY += h + C.blockquoteGapBelow;
        return;
      }

      // ── BR — line break: advance cursor by one line height ──
      // This ensures reaction equations or any content separated by <br>
      // tags render on separate lines rather than running together.
      if (tag === 'BR') {
        cursorY += C.paragraphLineHeight;
        return;
      }

      // ── SUB / SUP — inline subscript and superscript ──
      // These are rendered inline as smaller shifted text
      if (tag === 'SUB' || tag === 'SUP') {
        // Handled inline by getNodeText — skip standalone processing
        return;
      }

      // ── List items — rich inline renderer (handles SUB/SUP/BOLD inside li) ──
      if (tag === 'LI') {
        const liSegs = collectSegments(node);
        if (!liSegs.length) return;
        const liIndent = C.marginLeft + 5;
        const liWidth  = printW - 5;
        // Height pre-calc for bullet dot positioning
        const liPlain = liSegs.map(s => s.text).join('').replace(/\s+/g, ' ').trim();
        if (!liPlain) return;
        pdf.setFontSize(C.paragraphFontSize); setFont('normal');
        const liLines = pdf.splitTextToSize(liPlain, liWidth);
        const liH = liLines.length * C.listItemLineHeight + C.listItemGapBelow;
        checkPage(liH + 2);
        // Bullet dot
        pdf.setFillColor(37, 99, 235);
        pdf.circle(C.marginLeft + 1.5, cursorY - 1, 1.2, 'F');
        renderSegments(liSegs, liIndent, liWidth, C.listItemLineHeight, C.listItemGapBelow);
        return;
      }

      // ── Paragraphs — with bold & highlight support ──
      if (tag === 'P') {
        // ── Exam-tag pill badges ─────────────────────────────────────────────
        // Supports two HTML patterns:
        //
        // Pattern A — one span per label (original format):
        //   <span class="exam-tag">JEE Advanced</span>
        //   <span class="exam-tag">NEET</span>
        //
        // Pattern B — single span, pipe-separated labels (new format):
        //   <span class="tag-badge">JEE | NEET | IIT-JAM | GATE</span>
        //
        // Detection: all element children must be SPANs whose class contains
        // 'exam', 'tag', or 'badge'. Whitespace text nodes between spans are ignored.
        {
          const childArr     = Array.from(node.childNodes);
          const elemChildren = childArr.filter(n => n.nodeType === 1); // element nodes only
          const textChildren = childArr.filter(n => n.nodeType === 3); // text nodes only

          const hasNonWhitespaceText = textChildren.some(t => t.textContent.trim() !== '');

          const allAreExamSpans = elemChildren.length > 0 && elemChildren.every(el => {
            return isExamTagSpan(el);
          });

          // Also detect mixed case: some exam-tag spans + other text/elements
          const someAreExamSpans = elemChildren.some(el => isExamTagSpan(el));

          // ── section-tag: <p><span class="section-tag">Complete Chapter Coverage</span></p> ──
          if (!hasNonWhitespaceText && elemChildren.length > 0 &&
              elemChildren.every(el => isSectionTagSpan(el))) {
            const labels = elemChildren.map(s => (s.textContent || '').trim()).filter(Boolean);
            if (labels.length) {
              renderPills(labels, [[2, 132, 199]], 7, 4, 2.5, 9, 2, 10);
              return;
            }
          }

          if (!hasNonWhitespaceText && allAreExamSpans) {
            // Extract labels — handle both patterns:
            // Pattern A: each span is one label → use span text directly
            // Pattern B: one span with pipe-separated text → split on '|'
            let labels = [];
            if (elemChildren.length === 1) {
              // Single span — split on '|' to get individual pill labels
              labels = (elemChildren[0].textContent || '')
                .split('|')
                .map(s => s.trim())
                .filter(Boolean);
            } else {
              // Multiple spans — each span = one label
              labels = elemChildren
                .map(s => (s.textContent || '').trim())
                .filter(Boolean);
            }

            if (labels.length) {
              const EXAM_COLORS = [[0,110,90],[50,80,110],[80,100,40],[120,60,20],[60,60,130],[20,100,100]];
              cursorY -= 2;
              renderPills(labels, EXAM_COLORS, 8, 4, 2.5, 9, 2, 10);
              return;
            }
          }

          // ── Mixed content: exam-tag spans + other text (e.g. "&nbsp;| Based on: ...") ──
          // Fires when:
          //   (a) some elem children are exam spans but not all, OR
          //   (b) all elem children are exam spans BUT there are also non-whitespace text nodes
          //       (e.g. &nbsp;|&nbsp; Based on: Atkins...)
          // Render the exam-tag spans as pills first, then render remaining text below.
          if (someAreExamSpans && (!allAreExamSpans || hasNonWhitespaceText)) {
            const examLabels = elemChildren
              .filter(el => isExamTagSpan(el))
              .map(s => (s.textContent || '').trim()).filter(Boolean);
            if (examLabels.length) {
              const EXAM_COLORS = [[0,110,90],[50,80,110],[80,100,40],[120,60,20],[60,60,130],[20,100,100]];
              renderPills(examLabels, EXAM_COLORS, 8, 4, 2.5, 9, 2, 8);
            }
            // Render remaining text (text nodes + non-exam spans), strip leading &nbsp;|&nbsp;
            const cloneForText = node.cloneNode(true);
            Array.from(cloneForText.querySelectorAll('span')).forEach(s => {
              if (isExamTagSpan(s)) s.parentNode.removeChild(s);
            });
            const remainSegs = collectSegments(cloneForText);
            if (remainSegs.length) {
              const remainText = remainSegs.map(s => s.text).join('').replace(/\s+/g, ' ').trim()
                .replace(/^[\u00A0\s]*\|[\u00A0\s]*/, ''); // strip leading &nbsp;|&nbsp; or | separator
              if (remainText) {
                pdf.setFontSize(C.paragraphFontSize); setFont('normal');
                const rLines = pdf.splitTextToSize(remainText, printW);
                checkPage(rLines.length * C.paragraphLineHeight + C.paragraphGapBelow);
                pdf.setTextColor(...C.bodyTextColor);
                pdf.text(rLines, C.marginLeft, cursorY);
                cursorY += rLines.length * C.paragraphLineHeight + C.paragraphGapBelow;
              }
            }
            return;
          }
        }

        // ── Early-exit: P that wraps only an image (e.g. <p style="text-align:left;"><img ...></p>)
        //    Also handles <p><a href="..."><img ...></a></p> Blogger patterns
        {
          const pImgEl = node.querySelector('img');
          const pTexts = getNodeText(node).trim().replace(/\s+/g, '');
          if (pImgEl && pTexts.length === 0) {
            // Only child content is image — delegate to IMG handler
            await processNode(pImgEl);
            return;
          }
        }

        // Rich inline render — collectSegments handles bold/sub/sup in any nesting
        const segments = collectSegments(node);
        if (!segments.length) return;
        renderSegments(segments, C.marginLeft, printW, C.paragraphLineHeight, C.paragraphGapBelow);
        return;
      }

      // ── Inline text elements outside P (B, STRONG, MARK etc.) ──
      if (['B','STRONG','EM','I','FONT','MARK','S','U','CITE','ABBR'].includes(tag)) {
        const text = getNodeText(node).trim().replace(/\s+/g, ' ');
        if (!text) return;
        const isBold = (tag === 'B' || tag === 'STRONG');
        const isMark = (tag === 'MARK');
        setFont(isBold ? 'bold' : 'normal');
        pdf.setFontSize(C.paragraphFontSize);
        const lines = pdf.splitTextToSize(text, printW);
        const h = lines.length * C.paragraphLineHeight + C.paragraphGapBelow;
        checkPage(h);
        if (isMark) {
          const fs = C.paragraphFontSize; const ptMM = 0.3528;
          lines.forEach((line, li) => {
            const lw = pdf.getStringUnitWidth(line) * fs * ptMM;
            pdf.setFillColor(255, 255, 0);
            pdf.rect(C.marginLeft, cursorY + li * C.paragraphLineHeight - fs * ptMM + 0.3, lw, fs * ptMM + 1, 'F');
          });
        }
        pdf.setTextColor(...C.bodyTextColor);
        pdf.text(lines, C.marginLeft, cursorY);
        cursorY += h;
        return;
      }

      // ── DIV / SECTION / ARTICLE — recurse into children ──
      // But first check: if this DIV contains ONLY inline/text content (like reaction-box),
      // render it as a styled block instead of recursing (avoids lost text)
      if (tag === 'DIV' || tag === 'SECTION' || tag === 'ARTICLE') {

        // ── Detect styled info / tip / warning / highlight / tooltip boxes ──
        const divCls = (
          (node.className || '') + ' ' +
          (node.getAttribute('id') || '') + ' ' +
          (node.getAttribute('data-type') || '') + ' ' +
          (node.getAttribute('role') || '')
        ).toLowerCase();

        const BOX_DETECT = {
          // nchem-box-info / generic info/note patterns
          info:      /nchem-box-info|\b(info|note|information|notice|did\.you\.know)\b/,
          // nchem-box-tip / nchem-box-success / green success boxes
          tip:       /nchem-box-tip|nchem-box-success|\b(tip|success|pro\.tip|helpful|good\.to\.know)\b/,
          // nchem-box-danger / red warning patterns
          warning:   /nchem-box-danger|\b(warn|warning|caution|danger|alert|error|important)\b/,
          // nchem-memory / highlight/callout patterns
          highlight: /nchem-memory|\b(highlight|callout|feature|key\.point|summary|definition|memory)\b/,
          // generic tooltip/hint
          tooltip:   /\b(tooltip|hint|example|fact|side\.note)\b/,
        };

        // Visual design per box type
        // headerBg = full-width header bar colour; accent = left border + icon circle
        const BOX_STYLES = {
          info: {
            outerBg:   [235, 246, 255], headerBg:  [37,  99,  235],
            accent:    [37,  99,  235], textClr:   [22,  51, 120],
            bodyClr:   [30,  30,  50],  borderClr: [59, 130, 246],
            icon: '\u2139', label: 'INFORMATION',
          },
          tip: {
            outerBg:   [236, 253, 245], headerBg:  [5,  150, 105],
            accent:    [5,  150, 105],  textClr:   [255, 255, 255],
            bodyClr:   [20,  60,  40],  borderClr: [16, 185, 129],
            icon: '\u2714', label: 'TIP',
          },
          warning: {
            outerBg:   [255, 248, 230], headerBg:  [217, 119,   6],
            accent:    [180,  83,   9], textClr:   [255, 255, 255],
            bodyClr:   [80,  40,   0],  borderClr: [245, 158,  11],
            icon: '\u26a0', label: 'IMPORTANT',
          },
          highlight: {
            outerBg:   [240, 238, 255], headerBg:  [79,  70, 229],
            accent:    [79,  70, 229],  textClr:   [255, 255, 255],
            bodyClr:   [35,  20,  90],  borderClr: [99, 102, 241],
            icon: '\u2605', label: 'KEY POINT',
          },
          tooltip: {
            outerBg:   [246, 248, 250], headerBg:  [71,  85, 105],
            accent:    [71,  85, 105],  textClr:   [255, 255, 255],
            bodyClr:   [40,  40,  40],  borderClr: [148, 163, 184],
            icon: '\u25c6', label: 'NOTE',
          },
        };

        let detectedBox = null;
        for (const [bType, rx] of Object.entries(BOX_DETECT)) {
          if (rx.test(divCls)) { detectedBox = bType; break; }
        }

        if (detectedBox) {
          const B = BOX_STYLES[detectedBox];

          // ── Title: only use heading elements (h1-h6), never steal bold/strong from body ──
          // Prefer the blog's own title div class, then fall back to semantic headings
          const headingEl = node.querySelector(
            '.nchem-box-title, .nchem-memory-title, .nchem-diagram-title,\
             h1, h2, h3, h4, h5, h6'
          );
          let boxTitle    = headingEl ? headingEl.innerText.trim() : B.label;
          if (!boxTitle) boxTitle = B.label;

          // ── Body: use innerText so block elements (li, p) produce newlines naturally ──
          // Strip the heading text from the top if it's there, then split on newlines
          // so each list-item / paragraph renders as its own line (no mashing).
          let rawInner = (node.innerText || getNodeText(node)).trim();
          if (headingEl) {
            const hTxt = headingEl.innerText.trim();
            if (rawInner.startsWith(hTxt)) rawInner = rawInner.slice(hTxt.length).trim();
          }
          // Collapse horizontal whitespace but keep line separators
          rawInner = rawInner.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n');

          if (!rawInner && !boxTitle) { /* empty box — skip */ }
          else {
            const PAD_L  = 5;
            const PAD_R  = 5;
            const textW  = printW - PAD_L - PAD_R;
            // BODY_LH removed — bodyH is now measured via measureBoxBody()
            const BODY_TOP = 10;
            const BODY_BOT = 3;

            pdf.setFontSize(9.5);
            setFont('bold');
            const titleLines = pdf.splitTextToSize(boxTitle, textW - 4);

            // Measure body height using the same DOM-based logic as renderBoxBody()
            // so the pre-drawn border always exactly wraps the actual rendered content.
            const measuredBodyContent = rawInner
              ? measureBoxBody(node, headingEl, textW)
              : 0;
            const bodyH = measuredBodyContent > 0
              ? BODY_TOP + measuredBodyContent + BODY_BOT
              : 4;
            // Calculate real total height based on box type
            // All box types with header bars use HDR_H=10 (tip/info) or 9 (warning) or 11 (highlight) or 8 (tooltip)
            // Use 11 (max) so checkPage never under-estimates
            const hdrH = 11;
            const realTotalH = hdrH + bodyH;
            // If box fits on current page use it, otherwise start new page
            checkPage(realTotalH + 8);
            const bx = C.marginLeft;
            const by = cursorY;

            // ═══════════════════════════════════════════════════
            // DESIGN PER BOX TYPE — each has a unique visual style
            // ═══════════════════════════════════════════════════

            if (detectedBox === 'info') {
              // ── INFO BOX: Clean white card with blue top accent bar + label pill ──
              const HDR_H = 10;
              const totalH = HDR_H + bodyH;
              // White card background
              pdf.setFillColor(255, 255, 255);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'F');
              // Thin blue top bar (full width, rounded top only)
              pdf.setFillColor(37, 99, 235);
              pdf.roundedRect(bx, by, printW, HDR_H, 3, 3, 'F');
              pdf.rect(bx, by + HDR_H - 3, printW, 3, 'F');
              // Outer border thin
              pdf.setDrawColor(37, 99, 235);
              pdf.setLineWidth(0.3);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'S');
              // Title on blue bar — white text
              pdf.setTextColor(255, 255, 255);
              setFont('bold');
              pdf.setFontSize(9);
              pdf.text(boxTitle.toUpperCase(), bx + PAD_L, by + 6.5);
              // Body text — rich render (handles sub/sup/bold/highlight)
              if (rawInner) {
                cursorY = by + HDR_H + BODY_TOP;
                cursorY = renderBoxBody(node, headingEl, bx + PAD_L, textW, [30, 50, 100], cursorY);
              }
              cursorY = Math.max(cursorY, by + totalH) + 10;

            } else if (detectedBox === 'tip') {
              // ── TIP BOX: Green header bar (same pattern as INFO/WARNING/HIGHLIGHT) ──
              const HDR_H = 10;
              const totalH = HDR_H + bodyH;
              // Light green card background
              pdf.setFillColor(236, 253, 245);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'F');
              // Solid green header bar (rounded top only — same technique as INFO)
              pdf.setFillColor(5, 150, 105);
              pdf.roundedRect(bx, by, printW, HDR_H, 3, 3, 'F');
              pdf.rect(bx, by + HDR_H - 3, printW, 3, 'F');
              // Outer border
              pdf.setDrawColor(16, 185, 129);
              pdf.setLineWidth(0.3);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'S');
              // Checkmark icon + title on green bar — white text
              pdf.setTextColor(255, 255, 255);
              setFont('bold');
              pdf.setFontSize(9);
              pdf.text('\u2714  ' + boxTitle.toUpperCase(), bx + PAD_L, by + 6.5);
              // Body text — rich render (handles sub/sup/bold/highlight)
              if (rawInner) {
                cursorY = by + HDR_H + BODY_TOP;
                cursorY = renderBoxBody(node, headingEl, bx + PAD_L, textW, [20, 60, 40], cursorY);
              }
              cursorY = Math.max(cursorY, by + totalH) + 10;

            } else if (detectedBox === 'warning') {
              // ── WARNING BOX: Warm amber, dashed border, bold uppercase title ──
              const HDR_H = 9;
              const totalH = HDR_H + bodyH;
              // Warm amber background
              pdf.setFillColor(255, 251, 235);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'F');
              // Amber header strip (rounded top)
              pdf.setFillColor(245, 158, 11);
              pdf.roundedRect(bx, by, printW, HDR_H, 3, 3, 'F');
              pdf.rect(bx, by + HDR_H - 3, printW, 3, 'F');
              // Thin dashed-style border (drawn as thin solid — jsPDF no native dash)
              pdf.setDrawColor(217, 119, 6);
              pdf.setLineWidth(0.3);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'S');
              // Warning icon + title on amber bar
              pdf.setTextColor(255, 255, 255);
              setFont('bold');
              pdf.setFontSize(9);
              pdf.text('\u26A0  ' + boxTitle.toUpperCase(), bx + PAD_L, by + 6);
              // Body text — rich render (handles sub/sup/bold/highlight)
              if (rawInner) {
                cursorY = by + HDR_H + BODY_TOP;
                cursorY = renderBoxBody(node, headingEl, bx + PAD_L, textW, [92, 45, 0], cursorY);
              }
              cursorY = Math.max(cursorY, by + totalH) + 10;

            } else if (detectedBox === 'highlight') {
              // ── MEMORY/HIGHLIGHT BOX: Purple gradient feel, title centred, star icon ──
              const HDR_H = 11;
              const totalH = HDR_H + bodyH;
              // Light purple background
              pdf.setFillColor(245, 243, 255);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'F');
              // Deep purple header (rounded top)
              pdf.setFillColor(79, 70, 229);
              pdf.roundedRect(bx, by, printW, HDR_H, 3, 3, 'F');
              pdf.rect(bx, by + HDR_H - 3, printW, 3, 'F');
              // Thin border
              pdf.setDrawColor(99, 102, 241);
              pdf.setLineWidth(0.3);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'S');
              // Star + title centred on header
              pdf.setTextColor(255, 255, 255);
              setFont('bold');
              pdf.setFontSize(9.5);
              pdf.text('\u2605  ' + boxTitle, bx + printW / 2, by + 7.5, { align: 'center' });
              // Thin divider line between header and body
              pdf.setDrawColor(99, 102, 241);
              pdf.setLineWidth(0.3);
              pdf.line(bx + 4, by + HDR_H, bx + printW - 4, by + HDR_H);
              // Body text — rich render (handles sub/sup/bold/highlight)
              if (rawInner) {
                cursorY = by + HDR_H + BODY_TOP;
                cursorY = renderBoxBody(node, headingEl, bx + PAD_L, textW, [45, 30, 100], cursorY);
              }
              cursorY = Math.max(cursorY, by + totalH) + 10;

            } else {
              // ── TOOLTIP/NOTE BOX: Minimal grey, no header bar, just label + divider ──
              const LABEL_H = 8;
              const totalH  = LABEL_H + bodyH;
              // Very light grey background
              pdf.setFillColor(248, 249, 250);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'F');
              // Thin grey border
              pdf.setDrawColor(148, 163, 184);
              pdf.setLineWidth(0.3);
              pdf.roundedRect(bx, by, printW, totalH, 3, 3, 'S');
              // Diamond icon + label — dark grey, no background bar
              pdf.setTextColor(71, 85, 105);
              setFont('bold');
              pdf.setFontSize(8.5);
              pdf.text('\u25C6  ' + boxTitle.toUpperCase(), bx + PAD_L, by + 5.5);
              // Thin divider under label
              pdf.setDrawColor(203, 213, 225);
              pdf.setLineWidth(0.3);
              pdf.line(bx + PAD_L, by + LABEL_H - 1, bx + printW - PAD_R, by + LABEL_H - 1);
              // Body text — rich render (handles sub/sup/bold/highlight)
              if (rawInner) {
                cursorY = by + LABEL_H + BODY_TOP;
                cursorY = renderBoxBody(node, headingEl, bx + PAD_L, textW, [51, 65, 85], cursorY);
              }
              cursorY = Math.max(cursorY, by + totalH) + 10;
            }
            return;
          }
        }

        // Check if div has block-level children — if not, treat as text block
        const blockTags = ['P','H1','H2','H3','H4','H5','H6','UL','OL','TABLE','PRE','BLOCKQUOTE','DIV','SECTION','FIGURE','A','IMG','SVG','FIGCAPTION'];
        const hasBlockChild = Array.from(node.children).some(c => blockTags.includes(c.tagName.toUpperCase()));
        if (!hasBlockChild) {
          // ── BR-aware leaf DIV renderer ──────────────────────────────────────
          // Split the div's child nodes at every <br>, collect segments for each
          // line-group, then renderSegments each group separately. This ensures
          // reaction equations (or any BR-separated content) appear on individual
          // lines rather than being concatenated into one long run-on string.
          const hasBR = Array.from(node.childNodes).some(
            c => c.nodeType === Node.ELEMENT_NODE && c.tagName.toUpperCase() === 'BR'
          );
          if (hasBR) {
            // Walk child nodes, accumulating segments until a BR — then flush
            let lineNodes = [];
            const flushLine = () => {
              if (!lineNodes.length) return;
              // Build a temporary fragment so collectSegments can walk it
              const frag = document.createDocumentFragment();
              lineNodes.forEach(n => frag.appendChild(n.cloneNode(true)));
              const wrapper = document.createElement('span');
              frag.childNodes.forEach ? Array.from(frag.childNodes).forEach(n => wrapper.appendChild(n)) : null;
              // Simpler: collect segments directly from accumulated nodes
              const lineSegs = [];
              lineNodes.forEach(n => {
                const s = collectSegments(n);
                lineSegs.push(...s);
              });
              // Trim leading/trailing whitespace segments
              const plain = lineSegs.map(s => s.text).join('').trim();
              if (plain) renderSegments(lineSegs, C.marginLeft, printW, C.paragraphLineHeight, C.paragraphGapBelow);
              lineNodes = [];
            };
            for (const child of Array.from(node.childNodes)) {
              if (child.nodeType === Node.ELEMENT_NODE && child.tagName.toUpperCase() === 'BR') {
                flushLine();
              } else {
                lineNodes.push(child);
              }
            }
            flushLine(); // flush final line (no trailing BR)
            return;
          }
          // No BR — plain leaf div, rich render as before
          const divSegs = collectSegments(node);
          if (divSegs.length) renderSegments(divSegs, C.marginLeft, printW, C.paragraphLineHeight, C.paragraphGapBelow);
          return;
        }
        // Container DIV — recurse into children
        for (const c of Array.from(node.childNodes)) { await processNode(c); }
        return;
      }

      // ── FIGCAPTION — render as caption text below diagrams ──
      if (tag === 'FIGCAPTION') {
        const figSegs = collectSegments(node);
        if (!figSegs.length) return;
        renderSegments(figSegs, C.marginLeft, printW, C.paragraphLineHeight - 0.5, C.paragraphGapBelow);
        return;
      }

      // ── SPAN — rich render so sub/sup inside spans works ──
      // Also handles standalone exam-tag / section-tag spans anywhere in the DOM.
      if (tag === 'SPAN') {
        const EXAM_COLORS    = [[0,110,90],[50,80,110],[80,100,40],[120,60,20],[60,60,130],[20,100,100]];
        const SECTION_COLORS = [[2, 132, 199]]; // single blue — section pills are one per P

        // ── Single exam-tag span ──
        if (isExamTagSpan(node)) {
          const lbl = (node.textContent || '').trim();
          if (lbl) renderPills([lbl], EXAM_COLORS, 8, 4, 2.5, 9, 2, 6);
          return;
        }

        // ── Single section-tag span ──
        if (isSectionTagSpan(node)) {
          const lbl = (node.textContent || '').trim();
          if (lbl) renderPills([lbl], SECTION_COLORS, 7, 4, 2.5, 9, 2, 5);
          return;
        }

        // ── Span containing multiple exam-tag children (e.g. inside a wrapper span) ──
        const examChildren = Array.from(node.querySelectorAll('span')).filter(isExamTagSpan);
        if (examChildren.length > 0) {
          const labels = examChildren.map(s => (s.textContent || '').trim()).filter(Boolean);
          if (labels.length) renderPills(labels, EXAM_COLORS, 8, 4, 2.5, 9, 2, 6);
          return;
        }

        // ── Default: rich render for normal spans (sub/sup, bold, highlight) ──
        const spanSegs = collectSegments(node);
        if (spanSegs.length) renderSegments(spanSegs, C.marginLeft, printW, C.paragraphLineHeight, C.paragraphGapBelow);
        return;
      }

      // ── Fallback: recurse ──
      for (const c of Array.from(node.childNodes)) { await processNode(c); }
    }

    for (const child of Array.from(postBody.childNodes)) { await processNode(child); }

    // ── FOOTER ──
    cursorY += C.footerGapAbove;
    checkPage(C.footerHeight + 5);
    pdf.setFillColor(0, 126, 101);
    pdf.rect(C.marginLeft, cursorY, printW, C.footerHeight, 'F');
    pdf.setTextColor(255, 255, 255);
    setFont('bold');
    pdf.setFontSize(C.footerFontSize);
    pdf.text('sudhirnama.in', pageW / 2, cursorY + 9, { align: 'center' });
    setFont('normal');
    pdf.setFontSize(10);
    pdf.setTextColor(200, 240, 230);
    pdf.text('\u00A9 2026 Sudhir Nama | All Rights Reserved \u00B7 Premium Resource', pageW / 2, cursorY + 16, { align: 'center' });

    // ── PAGE NUMBERS ──
    const totalPages = pdf.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      pdf.setPage(i);
      pdf.setTextColor(160, 160, 160);
      pdf.setFontSize(10);
      setFont('normal');
      pdf.text('Page ' + i + ' of ' + totalPages, pageW - C.marginRight, pageH - 8, { align: 'right' });
      pdf.text('sudhirnama.in', C.marginLeft, pageH - 8);
    }

    pdf.save(postTitle.replace(/[^a-z0-9]/gi, '_') + '.pdf');

  } catch (err) {
    alert('PDF error: ' + err.message);
  }

  btn.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" style="margin-right:8px;"><path d="M7 18H17V16H7V18Z" fill="#FF0000"/><path d="M17 14H7V12H17V14Z" fill="#FF0000"/><path d="M7 10H11V8H7V10Z" fill="#FF0000"/><path fill-rule="evenodd" clip-rule="evenodd" d="M6 2C4.34315 2 3 3.34315 3 5V19C3 20.6569 4.34315 22 6 22H18C19.6569 22 21 20.6569 21 19V9L14 2H6ZM13 4L19 10H13V4ZM5 19V5C5 4.44772 5.44772 4 6 4H11V12H19V19C19 19.5523 18.5523 20 18 20H6C5.44772 20 5 19.5523 5 19Z" fill="#FF0000"/></svg>Download As PDF';
  btn.disabled = false;
}
